ol-sm-6">                    <label>Question</label>                    <input type="text" name="title[]" class="form-control" placeholder="Enter Question">                </div>                <div class="col-sm-6">                    <label>Answer</label>                    <textarea name="description[]" class="form-control textarea" placeholder="Enter Answer"></textarea>                </div>            </div>            <button type="button" class="btn btn-danger remove-faq mt-2">Remove</button>        `;        faqContainer.appendChild(newFaq);        // Initialize Summernote for dynamically added textareas        $(newFaq).find('.textarea').summernote({            height: 200,            tabsize: 2,            codeviewFilter: false,            codeviewIframeFilter: false,            codemirror: { theme: 'monokai' },            disableDragAndDrop: true,            toolbar: [                ['style', ['bold', 'italic', 'underline', 'clear']],                ['font', ['strikethrough', 'superscript', 'subscript']],                ['fontsize', ['fontsize']],                ['color', ['color']],                ['para', ['ul', 'ol', 'paragraph']],                ['insert', ['link', 'picture', 'video']],                ['view', ['codeview']]            ]        });    });    // Attach event listener to remove dynamically added FAQ items    faqContainer.addEventListener("click", function (event) {        if (event.target.classList.contains("remove-faq")) {            event.target.closest(".faq-item").remove();        }    });});    </script></script>